export default {"7.4-03": {"expr": "−12 + 12","why": "Down is negative and up is positive. Add the two changes.","story": [["down 12 feet","−12"],["up 12 feet","12"]]},"7.4-07": {"expr": "−6 + 15","why": "Start at −6. Warming up adds 15.","story": [["−6°F","−6"],["warms up 15°F","15"]]},"7.4-12": {"expr": "3 − (−5)","why": "Distance is the bigger number minus the smaller number.","story": [["−5","−5"],["3","3"]]},"7.4-13": {"expr": "−2.4 − (−7.1)","why": "Distance is the bigger number minus the smaller number. −2.4 is bigger (closer to 0).","story": [["−2.4","−2.4"],["−7.1","−7.1"]]},"7.4-14": {"expr": "35 − (−120)","why": "How far apart = the higher one minus the lower one.","story": [["−120 m","−120"],["35 m","35"]]},"7.7-01": {"simp": "p + 0.1p","var": "the old price","why": "Going up 10% means the old price plus 10% of it. 10% is 0.1, so 10% of p is 0.1p.","story": [["A price p","p"],["goes up 10%","0.1p"]],"end": "1.1p means the new price is 110% of the old price."},"7.7-02": {"simp": "p − 0.2p","var": "the price before the sale","why": "20% off means the price minus 20% of it. 20% is 0.2, so 20% of p is 0.2p.","story": [["costs p dollars","p"],["20% off","0.2p"]],"end": "0.8p means you pay 80% of the price."},"7.7-03": {"write": "2n + 5","var": "the number","why": "Twice a number n is 2n. 5 more than that means add 5.","story": [["twice a number n","2n"],["5 more","5"]]},"7.7-04": {"simp": "2(L + 4)","var": "the length","why": "Perimeter is the length plus the width, twice: 2(L + 4).","story": [["length L","L"],["width 4","4"]],"end": "2L + 8 and 2(L + 4) are the same perimeter, written two ways."},"7.7-06": {"write": "{b/4} + 3","var": "the bill","why": "Four friends split the bill, so each pays b ÷ 4. Then each adds §3.","story": [["split a bill b","{b/4}"],["§3 tip","3"]]},"7.7-08": {"write": "500 − 25m","var": "the number of minutes","why": "It starts at 500 gallons. Each minute takes away 25 gallons, so m minutes take away 25m.","story": [["500 gallons","500"],["25 gallons each minute","25m"]]},"7.7-10": {"simp": "12x + 8x","var": "the number of hats, and also of scarves","why": "x hats at §12 each cost 12x. x scarves at §8 each cost 8x. Add them.","story": [["x hats at §12 each","12x"],["x scarves at §8 each","8x"]],"end": "Each hat and scarf together cost §20, so x of each cost 20x."},"7.8-01": {"expr": "−12.40 + 30 − 3(2.75)","why": "Start with what he has, add the deposit, and take away the fee 3 times.","story": [["−§12.40","−12.40"],["deposits §30","30"],["§2.75 fee 3 times","3(2.75)"]]},"7.8-02": {"expr": "3 × 2{1/4}","why": "Triple means multiply by 3.","story": [["2{1/4} cups","2{1/4}"],["triple it","3"]]},"7.8-03": {"expr": "−4.5 − 3.2 + 6","why": "Dropped means subtract; rose means add.","story": [["−4.5°C","−4.5"],["dropped 3.2°C","3.2"],["rose 6°C","6"]]},"7.8-04": {"expr": "8 − 3 × {3/4}","why": "Start with 8 feet and take away {3/4} foot, 3 times.","story": [["8 feet","8"],["{3/4} foot three times","3 × {3/4}"]]},"7.8-06": {"expr": "15.50 × 6{1/2}","why": "Pay = pay per hour × hours.","story": [["§15.50 an hour","15.50"],["6{1/2} hours","6{1/2}"]]},"7.8-07": {"expr": "−1.35 × 5","why": "A loss is negative. It happened 5 times, so multiply.","story": [["lost §1.35","−1.35"],["5 days","5"]]},"7.8-09": {"expr": "{2/5} × 30 + 4.5","why": "{2/5} full means {2/5} of 30 gallons. Then add 4.5.","story": [["{2/5} full","{2/5}"],["30 gallons","30"],["add 4.5 gallons","4.5"]]},"7.9-09": {"eq": "25 + 15m = 130","var": "the number of months","why": "What you paid = the joining fee + §15 for each month, m.","story": [["§25 to join","25"],["§15 a month","15m"],["§130","130"]]},"7.9-10": {"eq": "3t = 12 + 18","var": "what each friend paid","why": "Each friend pays t, so together they pay 3t. That covers three §4 snacks (§12) and the §18 pizza.","story": [["Three friends","3t"],["§4 snack","12"],["§18 pizza","18"]]},"7.9-14": {"eq": "9t + 4 ≤ 40","var": "the number of tickets","why": "Tickets cost §9 each, so t tickets cost 9t. Add the popcorn. You can spend at most §40, so use ≤.","story": [["§9 each","9t"],["§4 on popcorn","4"],["You have §40","40"]]},"7.7-11": {"simp": "p − 0.15p","var": "the regular price","why": "Discounted by 15% means the price minus 15% of it. 15% is 0.15, so 15% of p is 0.15p.","story": [["regular price p","p"],["discounted by 15%","0.15p"]],"end": "p − 0.15p and 0.85p are the same sale price, written two ways."},"7.7-12": {"simp": "d + 0.07d","var": "the purchase before tax","why": "The tax adds 7% of d. 7% is 0.07, so the total is d + 0.07d.","story": [["purchase of d dollars","d"],["7% sales tax","0.07d"]],"end": "1.07d means the total is 107% of the purchase."},"7.7-13": {"simp": "4(s + 2)","var": "the old side length","why": "Each new side is s + 2. A square has 4 equal sides, so the perimeter is 4 times (s + 2).","story": [["increased by 2 inches","2"],["A square","4(s + 2)"]],"end": "4(s + 2) and 4s + 8 are the same perimeter, written two ways."},"7.7-17": {"simp": "0.9(1.3w)","var": "the wholesale price","why": "A 30% markup makes the price w + 0.3w = 1.3w. A 10% discount leaves 90% of that price, so multiply by 0.9.","story": [["marks up wholesale book prices w by 30%","1.3w"],["10% loyalty discount","0.9(1.3w)"]],"end": "1.17w is 117% of w, so it's a 17% increase overall."},"7.7-19": {"simp": "0.92(0.92p)","var": "the starting population","why": "Each 8% decrease leaves 92% of what was there. After last year the population is 0.92p. This year's 8% comes off 0.92p, not p, so multiply by 0.92 again.","story": [["decreased by 8% last year","0.92p"],["decreased by 8% again this year","0.92(0.92p)"]],"end": "0.8464p is about 84.6% of p. The student took 8% off the original p twice."},"8.11-13": {"eq": "20 + 15m = 50 + 10m","var": "the number of months","why": "Each gym's cost is its joining fee plus its monthly price times the months, m. The costs are the same, so set them equal.","story": [["§20 to join","20"],["§15 a month","15m"],["§50 to join","50"],["§10 a month","10m"]]},"8.11-14": {"eq": "2w + 2(w + 5) = 46","var": "the width","why": "Let w be the width. The length is 5 more, w + 5. Perimeter = 2 widths + 2 lengths.","story": [["5 more than its width","2(w + 5)"],["perimeter is 46","46"]],"then": [{"label": "Length","expr": "w + 5"}]},"8.11-15": {"eq": "x + (x + 3) + (2x − 1) = 30","var": "the shortest side","why": "The perimeter is all three sides added together.","story": [["x + 3","x + 3"],["2x − 1","2x − 1"],["perimeter is 30","30"]],"then": [{"label": "Longest side, 2x − 1","expr": "2x − 1"}]},"AlgI.11-01": {"eq": "60 − 4d < 20","var": "the number of days","why": "You start with §60 and lose §4 each day, so after d days you have 60 − 4d. That has to be less than §20.","story": [["§60","60"],["§4 a day","−4d"],["less than §20","20"]]},"AlgI.11-09": {"eq": "82 + 91 + x ≥ 264","var": "the 3rd test score","why": "An average of at least 88 over 3 tests means the 3 scores add up to at least 3 × 88 = 264.","story": [["82","82"],["91","91"],["average of at least 88","264"]]},"AlgI.11-10": {"write": "45 + 12w = 165","var": "the number of weeks","why": "She starts with §45 and adds §12 each week, so after w weeks she has 45 + 12w. That has to reach §165.","story": [["has §45","45"],["§12 per week","12w"],["costs §165","165"]]},"AlgI.11-11": {"write": "700 + 60b ≤ 2500","var": "the number of boxes","why": "The load is the 700-pound crate plus 60 pounds for each box, 60b. At most 2,500 means it can equal 2,500 or be less: ≤.","story": [["700-pound crate","700"],["60 pounds each","60b"],["at most 2,500 pounds","2500"]]}};
